#!/usr/bin/env python3

from __future__ import annotations

import os
import pathlib
import subprocess
import sys


VERSION = "0.4.2"
ISSUES_URL = "https://github.com/nuta/nsh/issues"
DEFAULT_PROMPT = r"\{cyan}\{bold}\{current_dir} $\{reset} "
DESCRIPTION = "A command-line shell that focuses on performance and productivity."


HELP_TEMPLATE = """nsh {version}
A command-line shell that focuses on performance and productivity.

USAGE:
    {prog} [FLAGS] [OPTIONS] [FILE]

FLAGS:
    -h, --help       Prints help information
    -l, --login      Behave like a login shell
        --norc       Don't load nshrc
        --version    Print the version

OPTIONS:
    -c <command>        The command to be executed

ARGS:
    <FILE>    The file to be executed
"""


class CliError(Exception):
    def __init__(self, message: str, usage: str) -> None:
        super().__init__(message)
        self.message = message
        self.usage = usage


class ParsedArgs:
    def __init__(self) -> None:
        self.command: str | None = None
        self.file: str | None = None
        self.help = False
        self.login = False
        self.norc = False
        self.version = False


def program_name() -> str:
    name = pathlib.Path(sys.argv[0]).name
    return name or "executable"


def shell_home() -> pathlib.Path:
    home = os.environ.get("HOME")
    if home:
        return pathlib.Path(home)
    return pathlib.Path.home()


def touch_log_file() -> None:
    home = shell_home()
    home.mkdir(parents=True, exist_ok=True)
    (home / ".nsh.log").touch(exist_ok=True)


def touch_history_file() -> None:
    home = shell_home()
    home.mkdir(parents=True, exist_ok=True)
    (home / ".nsh_history").touch(exist_ok=True)


def append_log(text: str) -> None:
    path = shell_home() / ".nsh.log"
    try:
        with path.open("a", encoding="utf-8", errors="replace") as handle:
            handle.write(text)
            if text and not text.endswith("\n"):
                handle.write("\n")
    except OSError:
        pass


def print_help() -> None:
    sys.stdout.write(HELP_TEMPLATE.format(version=VERSION, prog=program_name()))


def parse_error_usage() -> str:
    return f"USAGE:\n    {program_name()} [FLAGS] [OPTIONS] [FILE]\n"


def parse_error_usage_c() -> str:
    return f"USAGE:\n    {program_name()} -c <command>\n"


def fail_unknown_argument(arg: str) -> CliError:
    return CliError(
        f"error: Found argument '{arg}' which wasn't expected, or isn't valid in this context",
        parse_error_usage(),
    )


def raw_has_help(argv: list[str]) -> bool:
    for arg in argv:
        if arg == "--help":
            return True
        if arg.startswith("-") and not arg.startswith("--") and arg != "-":
            if "h" in arg[1:]:
                return True
    return False


def raw_has_version(argv: list[str]) -> bool:
    return "--version" in argv


def parse_args(argv: list[str]) -> ParsedArgs:
    parsed = ParsedArgs()
    positional: list[str] = []
    i = 0

    while i < len(argv):
        arg = argv[i]

        if arg == "--":
            positional.extend(argv[i + 1 :])
            break

        if arg.startswith("--"):
            if arg == "--help":
                parsed.help = True
            elif arg == "--version":
                parsed.version = True
            elif arg == "--login":
                parsed.login = True
            elif arg == "--norc":
                parsed.norc = True
            else:
                raise fail_unknown_argument(arg)
            i += 1
            continue

        if arg.startswith("-") and arg != "-":
            cluster = arg[1:]
            j = 0
            while j < len(cluster):
                short = cluster[j]
                if short == "h":
                    parsed.help = True
                    j += 1
                    continue
                if short == "l":
                    parsed.login = True
                    j += 1
                    continue
                if short == "c":
                    if j + 1 < len(cluster):
                        parsed.command = cluster[j + 1 :]
                    else:
                        if i + 1 >= len(argv):
                            raise CliError(
                                "error: The argument '-c <command>' requires a value but none was supplied",
                                parse_error_usage_c(),
                            )
                        i += 1
                        parsed.command = argv[i]
                    j = len(cluster)
                    continue
                raise fail_unknown_argument(f"-{short}")
            i += 1
            continue

        positional.append(arg)
        i += 1

    if positional:
        parsed.file = positional[0]
        if len(positional) > 1:
            raise fail_unknown_argument(positional[1])

    return parsed


def emit_cli_error(error: CliError) -> int:
    sys.stderr.write(f"{error.message}\n\n")
    sys.stderr.write(f"{error.usage}\n")
    sys.stderr.write("For more information try --help\n")
    return 1


def helper_script() -> pathlib.Path:
    current = pathlib.Path(__file__).resolve()
    candidates = [
        current.parent / "lib" / "nsh_init.bash",
        current.parent.parent / "lib" / "nsh_init.bash",
    ]
    for candidate in candidates:
        if candidate.exists():
            return candidate
    raise FileNotFoundError("missing lib/nsh_init.bash")


def base_env(parsed: ParsedArgs) -> dict[str, str]:
    env = dict(os.environ)
    env["NSH_LOAD_RC"] = "0" if parsed.norc else "1"
    env["NSH_DEFAULT_PROMPT"] = DEFAULT_PROMPT
    env["NSH_ISSUES_URL"] = ISSUES_URL
    env["BASH_ENV"] = str(helper_script())
    env["HISTFILE"] = "/dev/null"
    return env


def normalize_returncode(returncode: int) -> int:
    if returncode < 0:
        return 128 + (-returncode)
    return returncode


def syntax_check(args: list[str], env: dict[str, str]) -> tuple[int, str]:
    check_env = dict(env)
    check_env.pop("BASH_ENV", None)
    proc = subprocess.run(
        args,
        env=check_env,
        stdin=subprocess.DEVNULL,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.PIPE,
        text=True,
    )
    return proc.returncode, proc.stderr


def rewrite_bash_error(stderr_text: str) -> str:
    lines = stderr_text.splitlines()
    rewritten = []
    for line in lines:
        if line.startswith("bash: "):
            rewritten.append("nsh: " + line[len("bash: ") :])
        else:
            rewritten.append(line)
    return "\n".join(rewritten)


def emit_parse_error(stderr_text: str) -> int:
    text = rewrite_bash_error(stderr_text).rstrip()
    if not text:
        text = "nsh: parse error"
    sys.stderr.write(f"{text}\n")
    append_log(text)
    return 255


def emit_missing_file(path: str) -> int:
    message = (
        "nsh: panicked at src/main.rs:114:34:\n"
        f'failed to open the file: Os {{ code: 2, kind: NotFound, message: "No such file or directory" }}\n\n'
        f"nsh: Something went wrong. Check out ~/.nsh.log and please file this bug on GitHub: {ISSUES_URL}\n"
    )
    sys.stderr.write(message)
    append_log(
        "panicked at src/main.rs:114:34:\n"
        f'failed to open the file: Os {{ code: 2, kind: NotFound, message: "No such file or directory" }}'
    )
    return 101


def run_command(command: str, parsed: ParsedArgs) -> int:
    env = base_env(parsed)
    check_code, check_stderr = syntax_check(
        ["bash", "--noprofile", "--norc", "-n", "-c", command, ""],
        env,
    )
    if check_code != 0:
        return emit_parse_error(check_stderr)

    proc = subprocess.run(
        ["bash", "--noprofile", "--norc", "-c", command, ""],
        env=env,
    )
    code = normalize_returncode(proc.returncode)
    return 255 if code == 2 else code


def run_script(path: str, parsed: ParsedArgs) -> int:
    touch_history_file()
    script_path = pathlib.Path(path)
    if not script_path.exists():
        return emit_missing_file(path)

    env = base_env(parsed)
    check_code, check_stderr = syntax_check(
        ["bash", "--noprofile", "--norc", "-n", str(script_path)],
        env,
    )
    if check_code != 0:
        return emit_parse_error(check_stderr)

    proc = subprocess.run(
        ["bash", "--noprofile", "--norc", str(script_path)],
        env=env,
    )
    code = normalize_returncode(proc.returncode)
    return 255 if code == 2 else code


def run_interactive(parsed: ParsedArgs) -> int:
    touch_history_file()
    if not sys.stdout.isatty():
        sys.stderr.write("nsh: warning: stdout is not a tty\n")
        return 0

    env = base_env(parsed)
    argv = ["bash", "--noprofile", "--norc", "--rcfile", str(helper_script()), "-i"]
    os.execvpe("bash", argv, env)
    return 127


def main() -> int:
    touch_log_file()

    argv = sys.argv[1:]
    if raw_has_help(argv):
        print_help()
        return 0
    if raw_has_version(argv):
        sys.stdout.write(f"{VERSION}\n")
        return 0

    try:
        parsed = parse_args(argv)
    except CliError as error:
        return emit_cli_error(error)

    if parsed.help:
        print_help()
        return 0
    if parsed.version:
        sys.stdout.write(f"{VERSION}\n")
        return 0
    if parsed.command is not None:
        touch_history_file()
        return run_command(parsed.command, parsed)
    if parsed.file is not None:
        return run_script(parsed.file, parsed)
    return run_interactive(parsed)


if __name__ == "__main__":
    raise SystemExit(main())

